395	  /**
396	   * GET: /api/items/:id/cover
397	   *
398	   * @param {LibraryItemControllerRequest} req
399	   * @param {Response} res
400	   */
401	  async getCover(req, res) {
402	    const {
403	      query: { width, height, format, raw }
404	    } = req
405	
406	    if (req.query.ts) res.set('Cache-Control', 'private, max-age=86400')
407	
408	    const libraryItemId = req.params.id
409	    if (!libraryItemId) {
410	      return res.sendStatus(400)
411	    }
412	
413	    if (raw) {
414	      const coverPath = await Database.libraryItemModel.getCoverPath(libraryItemId)
415	      if (!coverPath || !(await fs.pathExists(coverPath))) {
416	        return res.sendStatus(404)
417	      }
418	      // any value
419	      if (global.XAccel) {
420	        const encodedURI = encodeUriPath(global.XAccel + coverPath)
421	        Logger.debug(`Use X-Accel to serve static file ${encodedURI}`)
422	        return res.status(204).header({ 'X-Accel-Redirect': encodedURI }).send()
423	      }
424	      return res.sendFile(coverPath)
425	    }
426	
427	    const options = {
428	      format: format || (reqSupportsWebp(req) ? 'webp' : 'jpeg'),
429	      height: clampPositiveInt(height ? parseInt(height) : null, 4096),
430	      width: clampPositiveInt(width ? parseInt(width) : null, 4096)
431	    }
432	    return CacheManager.handleCoverCache(res, libraryItemId, options)
433	  }
