547	  /**
548	   * POST: /api/items/batch/delete
549	   * Batch delete library items. Will delete from database and file system if hard delete is requested.
550	   * Optional query params:
551	   * ?hard=1
552	   *
553	   * @this {import('../routers/ApiRouter')}
554	   *
555	   * @param {RequestWithUser} req
556	   * @param {Response} res
557	   */
558	  async batchDelete(req, res) {
559	    if (!req.user.canDelete) {
560	      Logger.warn(`[LibraryItemController] User "${req.user.username}" attempted to delete without permission`)
561	      return res.sendStatus(403)
562	    }
563	    const hardDelete = req.query.hard == 1 // Delete files from filesystem
564	
565	    const { libraryItemIds } = req.body
566	    if (!libraryItemIds?.length || !Array.isArray(libraryItemIds)) {
567	      return res.status(400).send('Invalid request body')
568	    }
569	
570	    const itemsToDelete = await Database.libraryItemModel.findAllExpandedWhere({
571	      id: libraryItemIds
572	    })
573	
574	    if (!itemsToDelete.length) {
575	      return res.sendStatus(404)
576	    }
