629	   */
630	  async batchUpdate(req, res) {
631	    if (!req.user.canUpdate) {
632	      Logger.warn(`[LibraryItemController] User "${req.user.username}" attempted to batch update without permission`)
633	      return res.sendStatus(403)
634	    }
635	
636	    const updatePayloads = req.body
637	    if (!Array.isArray(updatePayloads) || !updatePayloads.length) {
638	      Logger.error(`[LibraryItemController] Batch update failed. Invalid payload`)
639	      return res.sendStatus(400)
640	    }
641	
642	    // Ensure that each update payload has a unique library item id
643	    const libraryItemIds = [...new Set(updatePayloads.map((up) => up?.id).filter((id) => id))]
644	    if (!libraryItemIds.length || libraryItemIds.length !== updatePayloads.length) {
645	      Logger.error(`[LibraryItemController] Batch update failed. Each update payload must have a unique library item id`)
646	      return res.sendStatus(400)
647	    }
648	
649	    // Get all library items to update
650	    const libraryItems = await Database.libraryItemModel.findAllExpandedWhere({
651	      id: libraryItemIds
652	    })
653	    if (updatePayloads.length !== libraryItems.length) {
654	      Logger.error(`[LibraryItemController] Batch update failed. Not all library items found`)
655	      return res.sendStatus(404)
656	    }
657	
658	    // Ensure user has permission to update these library items
659	    if (!ensureUserCanAccessLibraryItemsForBatch(req, res, libraryItems)) {
660	      return
661	    }
662	
663	    let itemsUpdated = 0
664	
665	    const seriesIdsRemoved = []
666	    const authorIdsRemoved = []
667	
668	    for (const updatePayload of updatePayloads) {
669	      const mediaPayload = updatePayload.mediaPayload
670	      const libraryItem = libraryItems.find((li) => li.id === updatePayload.id)
671	
672	      if (libraryItem.isPodcast && mediaPayload.autoDownloadSchedule && !cron.validate(mediaPayload.autoDownloadSchedule)) {
673	        Logger.warn(`[LibraryItemController] Invalid auto download schedule cron expression "${mediaPayload.autoDownloadSchedule}" for library item "${libraryItem.media.title}" - skipping update`)
674	        continue
675	      }
676	
677	      let hasUpdates = await libraryItem.media.updateFromRequest(mediaPayload)
678	
679	      if (libraryItem.isBook && Array.isArray(mediaPayload.metadata?.series)) {
680	        const seriesUpdateData = await libraryItem.media.updateSeriesFromRequest(mediaPayload.metadata.series, libraryItem.libraryId)
681	        if (seriesUpdateData?.seriesRemoved.length) {
682	          seriesIdsRemoved.push(...seriesUpdateData.seriesRemoved.map((se) => se.id))
683	        }
684	        if (seriesUpdateData?.seriesAdded.length) {
685	          seriesUpdateData.seriesAdded.forEach((se) => {
686	            Database.addSeriesToFilterData(libraryItem.libraryId, se.name, se.id)
687	          })
688	        }
689	        if (seriesUpdateData?.hasUpdates) {
690	          hasUpdates = true
691	        }
692	      }
693	
694	      if (libraryItem.isBook && Array.isArray(mediaPayload.metadata?.authors)) {
695	        const authorNames = mediaPayload.metadata.authors.map((au) => (typeof au.name === 'string' ? au.name.trim() : null)).filter((au) => au)
696	        const authorUpdateData = await libraryItem.media.updateAuthorsFromRequest(authorNames, libraryItem.libraryId)
697	        if (authorUpdateData?.authorsRemoved.length) {
698	          authorIdsRemoved.push(...authorUpdateData.authorsRemoved.map((au) => au.id))
699	          hasUpdates = true
700	        }
701	        if (authorUpdateData?.authorsAdded.length) {
702	          authorUpdateData.authorsAdded.forEach((au) => {
703	            Database.addAuthorToFilterData(libraryItem.libraryId, au.name, au.id)
704	          })
705	          hasUpdates = true
706	        }
707	      }
708	
709	      if (hasUpdates) {
710	        libraryItem.changed('updatedAt', true)
711	        await libraryItem.save()
712	
713	        await libraryItem.saveMetadataFile()
714	
715	        Logger.debug(`[LibraryItemController] Updated library item media "${libraryItem.media.title}"`)
716	        SocketAuthority.libraryItemEmitter('item_updated', libraryItem)
717	        itemsUpdated++
718	      }
719	    }
720	
721	    if (seriesIdsRemoved.length) {
722	      await this.checkRemoveEmptySeries(seriesIdsRemoved)
723	    }
724	    if (authorIdsRemoved.length) {
725	      await this.checkRemoveAuthorsWithNoBooks(authorIdsRemoved)
726	    }
727	
728	    res.json({
729	      success: true,
730	      updates: itemsUpdated
731	    })
732	  }
